        int numCases=s.nextInt();
        s.nextLine();
        for(int a=1;a<=numCases;a++)
        {
        	String line=s.nextLine();
        	line=line.toUpperCase();
        	System.out.println("Message #"+ a+ ": "+convertFullString(line));
        }
	}
}

